import React, { useState } from 'react';
import axios from 'axios';

export default function Login({ setToken, setRole }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleManualLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', { username, password });
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('role', res.data.role);
      setToken(res.data.token);
      setRole(res.data.role);
      window.location.href = '/dashboard';
    } catch (err) { alert('Login failed'); }
    setLoading(false);
  };

  const handleDerivLogin = () => { window.location.href = 'http://localhost:5000/api/auth/deriv/login'; };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header"><span className="logo">🔐</span><h1>Encrypted Dollar Zone</h1><p>Trade with Deriv • 3% Platform Fee • Copy Trading</p></div>
        <form onSubmit={handleManualLogin} className="login-form">
          <input type="text" placeholder="Username" value={username} onChange={(e) => setUsername(e.target.value)} required />
          <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required />
          <button type="submit" disabled={loading}>{loading ? 'Logging in...' : 'Login with Email'}</button>
        </form>
        <div className="divider">OR</div>
        <button onClick={handleDerivLogin} className="deriv-login-btn"><span>🔐</span> Login with Deriv Account</button>
        <div className="demo-credentials"><p>Demo Credentials:</p><code>admin / Admin123!</code><code>user / User123!</code></div>
      </div>
    </div>
  );
}
